To solve this problem, we need to generate a unified diff between two lists of lines using the longest common subsequence (LCS) algorithm. The unified diff format includes hunk headers that specify the range of lines in both input lists that have changed, and the body of each hunk shows the actual changes with prefixes indicating additions (`+`), deletions (`-`), and unchanged lines (space). The challenge is to ensure that the hunks are merged if they overlap and include up to `context` unchanged lines on each side. Additionally, we must handle edge cases such as empty input lists or identical input lists, which should result in an empty diff.

ANSWER:
```python
def unified_diff(a, b, context=3):
    def lcs(X, Y):
        m, n = len(X), len(Y)
        L = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if X[i - 1] == Y[j - 1]:
                    L[i][j] = L[i - 1][j - 1] + 1
                else:
                    L[i][j] = max(L[i - 1][j], L[i][j - 1])
        return L

    def backtrack(L, X, Y, i, j):
        path = []
        while i > 0 and j > 0:
            if X[i - 1] == Y[j - 1]:
                path.append((i - 1, j - 1))
                i -= 1
                j -= 1
            elif L[i - 1][j] > L[i][j - 1]:
                i -= 1
            else:
                j -= 1
        return path[::-1]

    if a == b:
        return []

    L = lcs(a, b)
    path = backtrack(L, a, b, len(a), len(b))

    diff = []
    i, j = 0, 0
    while i < len(a) or j < len(b):
        start_a, start_b = i + 1, j + 1
        unchanged = []
        while i < len(a) and j < len(b) and a[i] == b[j]:
            unchanged.append(a[i])
            i += 1
            j += 1

        if unchanged:
            diff.extend([' ' + line for line in unchanged])

        while i < len(a) and (not path or path[0][0] != i):
            diff.append('-' + a[i])
            i += 1

        while j < len(b) and (not path or path[0][1] != j):
            diff.append('+' + b[j])
            j += 1

        if path:
            end_a, end_b = path[0][0] + 1, path[0][1] + 1
            diff.append(f'@@ -{start_a},{end_a - start_a} +{start_b},{end_b - start_b} @@')
            while path and path[0][0] == i:
                diff.append(' ' + a[i])
                i += 1
                path.pop(0)

    return diff
```

