class WildcardTrie:
    def __init__(self):
        self.root = {}

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        if '$' not in node:
            node['$'] = True
            return True
        return False

    def remove(self, word):
        def _remove(node, word, depth):
            if depth == len(word):
                if '$' in node:
                    del node['$']
                    return True
                return False
            char = word[depth]
            if char in node and _remove(node[char], word, depth + 1):
                if not node[char]:
                    del node[char]
                    return True
            return False

        return _remove(self.root, word, 0)

    def search(self, pattern):
        def _search(node, pattern, depth):
            if depth == len(pattern):
                if '$' in node:
                    return [""]
                return []
            results = []
            char = pattern[depth]
            if char == '.':
                for key in node:
                    if key != '$':
                        results.extend([key + suffix for suffix in _search(node[key], pattern, depth + 1)])
            elif char in node:
                results.extend([char + suffix for suffix in _search(node[char], pattern, depth + 1)])
            return results

        raw_results = _search(self.root, pattern, 0)
        return sorted([pattern[:pattern.index('.')] + result for result in raw_results])

