        formula = self.formulas[cell]
        tokens = self._tokenize(formula)
        stack = []
        ops = {'+': (1, lambda x, y: x + y), '-': (1, lambda x, y: x - y), '*': (2, lambda x, y: x * y)}
        precedence = {op: prec for op, (prec, _) in ops.items()}

        def apply_operator():
            right = stack.pop()
            left = stack.pop()
            op = stack.pop()
            stack.append(ops[op][1](left, right))

