                    j += 1
                tokens.append(formula[i:j])
                i = j
            elif formula[i].isdigit():
                j = i
                while j < len(formula) and formula[j].isdigit():
                    j += 1
                tokens.append(int(formula[i:j]))
                i = j
            elif formula[i] in "+-*":
                tokens.append(formula[i])
                i += 1
            else:
                raise ValueError("Invalid character in formula")
