Edge cases include ensuring that the `unsubscribe` function returned by `on` correctly removes the event handler from the list of subscribers, and that the `emit` method correctly handles events with `void` payloads without requiring a second argument. We also need to ensure that the implementation works correctly when multiple handlers are subscribed to the same event and when events are emitted in rapid succession.

ANSWER:

```typescript
module.exports = (() => {
  class Bus<E extends Record<string, unknown>> {
    private handlers: { [K in keyof E]?: ((payload: E[K]) => void)[] } = {};

    on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
      if (!this.handlers[k]) {
        this.handlers[k] = [];
      }
      this.handlers[k]?.push(fn);
      return () => {
        this.handlers[k] = this.handlers[k]?.filter(f => f !== fn);
      };
    }

    emit<K extends keyof E>(k: K, payload?: E[K]): void {
      if (typeof payload === 'undefined' && typeof ({} as E)[k] !== 'undefined') {
        throw new Error(`Event ${String(k)} requires a payload`);
      }
      this.handlers[k]?.forEach(fn => fn(payload as E[K]));
    }
  }

  return { Bus };
})();
```

