  DeepPartial,
  applyPatch,
};

type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object ? (T[P] extends Function ? T[P] : DeepPartial<T[P]>) : T[P];
};

function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) {
    return base;
  }

  if (Array.isArray(patch)) {
    return [...patch];
  }

  if (typeof patch !== 'object' || patch === null) {
    return patch as T;
  }

  if (typeof base !== 'object' || base === null) {
    return patch as T;
