    if (Array.isArray(patch[key])) {
      result[key] = [...patch[key]];
    } else if (typeof patch[key] === 'object' && patch[key] !== null) {
      result[key] = applyPatch(result[key], patch[key]);
    } else {
      result[key] = patch[key];
    }
  }

  return result;
}
